"""Test models generated by code (no copyright risk): boxes, plates, extruded profiles, and the
writers for binary STL, text STL and 3MF. Used by the tests, the dev test set and the seed."""

import io
import struct
import zipfile
from collections.abc import Sequence

import numpy as np

from brimline_engine.files.mesh import Floats

Point = tuple[float, float]


def box(x: float, y: float, z: float, at: tuple[float, float, float] = (0, 0, 0)) -> Floats:
    """A closed box, faces pointing outwards, from `at` to `at + (x, y, z)`."""
    return extrude([(0, 0), (x, 0), (x, z), (0, z)], y, at)


def extrude(
    profile: Sequence[Point], depth: float, at: tuple[float, float, float] = (0, 0, 0)
) -> Floats:
    """A closed prism: a simple polygon in the x-z plane (any winding) pushed `depth` along y.
    Faces point outwards. Makes T shapes, L shapes and chamfers whose areas are easy by hand."""
    pts = list(profile)
    if _signed_area(pts) < 0:
        pts.reverse()
    caps = _ear_clip(pts)
    ox, oy, oz = at

    def p(i: int, y: float) -> list[float]:
        return [pts[i][0] + ox, y + oy, pts[i][1] + oz]

    tris: list[list[list[float]]] = []
    for a, b, c in caps:
        tris.append([p(a, 0), p(b, 0), p(c, 0)])
        tris.append([p(a, depth), p(c, depth), p(b, depth)])
    n = len(pts)
    for i in range(n):
        j = (i + 1) % n
        tris.append([p(j, 0), p(i, 0), p(i, depth)])
        tris.append([p(j, 0), p(i, depth), p(j, depth)])
    out = np.array(tris, dtype=np.float64)
    return out if _volume(out) > 0 else flip(out)


def hollow_box(x: float, y: float, z: float, wall: float) -> Floats:
    """A closed box with a closed inner cavity (faces pointing into the cavity): every wall is
    `wall` thick. Two shells that share no vertex."""
    inner = box(x - 2 * wall, y - 2 * wall, z - 2 * wall, (wall, wall, wall))
    return np.concatenate([box(x, y, z), flip(inner)])


def flip(tris: Floats) -> Floats:
    """The same triangles wound the other way: an inside-out surface."""
    return tris[:, [0, 2, 1]].copy()


def binary_stl(tris: Floats) -> bytes:
    out = io.BytesIO()
    out.write(b"Brimline generated test model".ljust(80, b" "))
    out.write(struct.pack("<I", len(tris)))
    for t in tris:
        out.write(struct.pack("<3f", 0, 0, 0))  # normals left zero: checkers use the winding
        out.write(struct.pack("<9f", *t.reshape(-1)))
        out.write(b"\0\0")
    return out.getvalue()


def text_stl(tris: Floats, name: str = "part") -> bytes:
    lines = [f"solid {name}"]
    for t in tris:
        lines += ["facet normal 0 0 0", " outer loop"]
        lines += [f"  vertex {v[0]:.6f} {v[1]:.6f} {v[2]:.6f}" for v in t]
        lines += [" endloop", "endfacet"]
    lines.append(f"endsolid {name}")
    return ("\n".join(lines) + "\n").encode("ascii")


def three_mf(
    tris: Floats,
    unit: str = "millimeter",
    doctype: bool = False,
    transform: str = "",
    copies: Sequence[str] = (),
    encoding: str = "utf-8",
) -> bytes:
    """A minimal 3MF package: content types, the root relationship and one mesh object, placed
    by a build item with an optional 3MF transform (12 numbers), plus one more item per entry of
    `copies` (each a transform). `encoding` writes the model in another text encoding."""
    corners = tris.reshape(-1, 3)
    keys, index = np.unique(np.round(corners, 6), axis=0, return_inverse=True)
    vertices = "".join(f'<vertex x="{v[0]:g}" y="{v[1]:g}" z="{v[2]:g}"/>' for v in keys)
    faces = "".join(f'<triangle v1="{a}" v2="{b}" v3="{c}"/>' for a, b, c in index.reshape(-1, 3))
    head = '<?xml version="1.0" encoding="UTF-8"?>'
    if doctype:
        head += '<!DOCTYPE model [<!ENTITY a "aaaaaaaaaa">]>'
    model = (
        f'{head}<model unit="{unit}" xmlns="http://schemas.microsoft.com/3dmanufacturing/core/2015/02">'
        f'<resources><object id="1" type="model"><mesh><vertices>{vertices}</vertices>'
        f"<triangles>{faces}</triangles></mesh></object></resources>"
        f'<build><item objectid="1"{f" transform={chr(34)}{transform}{chr(34)}" if transform else ""}/>'
        + "".join(f'<item objectid="1" transform="{t}"/>' for t in copies)
        + "</build></model>"
    )
    out = io.BytesIO()
    with zipfile.ZipFile(out, "w", zipfile.ZIP_DEFLATED) as z:
        z.writestr(
            "[Content_Types].xml",
            '<?xml version="1.0" encoding="UTF-8"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types">'
            '<Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/>'
            '<Default Extension="model" ContentType="application/vnd.ms-package.3dmanufacturing-3dmodel+xml"/></Types>',
        )
        z.writestr(
            "_rels/.rels",
            '<?xml version="1.0" encoding="UTF-8"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'
            '<Relationship Target="/3D/3dmodel.model" Id="rel0" Type="http://schemas.microsoft.com/3dmanufacturing/2013/01/3dmodel"/></Relationships>',
        )
        if encoding != "utf-8":
            model = model.replace('encoding="UTF-8"', f'encoding="{encoding.upper()}"', 1)
        z.writestr("3D/3dmodel.model", model.encode(encoding))
    return out.getvalue()


def _signed_area(pts: Sequence[Point]) -> float:
    return (
        sum(
            pts[i][0] * pts[(i + 1) % len(pts)][1] - pts[(i + 1) % len(pts)][0] * pts[i][1]
            for i in range(len(pts))
        )
        / 2.0
    )


def _ear_clip(pts: Sequence[Point]) -> list[tuple[int, int, int]]:
    """Triangulate a simple counter-clockwise polygon by cutting off ears."""
    idx = list(range(len(pts)))
    out: list[tuple[int, int, int]] = []

    def cross(o: Point, a: Point, b: Point) -> float:
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    while len(idx) > 3:
        for k in range(len(idx)):
            a, b, c = idx[k - 1], idx[k], idx[(k + 1) % len(idx)]
            if cross(pts[a], pts[b], pts[c]) <= 0:
                continue  # reflex or straight corner
            if any(
                cross(pts[a], pts[b], pts[q]) >= 0
                and cross(pts[b], pts[c], pts[q]) >= 0
                and cross(pts[c], pts[a], pts[q]) >= 0
                for q in idx
                if q not in (a, b, c)
            ):
                continue  # another corner inside: not an ear
            out.append((a, b, c))
            idx.pop(k)
            break
        else:
            raise ValueError("profile is not a simple polygon")
    out.append((idx[0], idx[1], idx[2]))
    return out


def _volume(tris: Floats) -> float:
    a, b, c = tris[:, 0], tris[:, 1], tris[:, 2]
    return float(np.einsum("ij,ij->i", a, np.cross(b, c)).sum() / 6.0)
